"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";

export type UpdateProfileData = {
  displayName?: string;
  bio?: string;
  favoriteGame?: string;
  city?: string;
  country?: string;
  avatarUrl?: string;
};

function toApiBody(data: UpdateProfileData) {
  return {
    display_name: data.displayName,
    bio: data.bio,
    favorite_game: data.favoriteGame,
    city: data.city,
    country: data.country,
    avatar_url: data.avatarUrl,
  };
}

export function useUpdateProfile() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: UpdateProfileData) => {
      const res = await fetch("/api/players/me", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(toApiBody(data)),
      });
      if (!res.ok) {
        const error = await res.json().catch(() => ({}));
        throw new Error(String(error.detail ?? error.message ?? "Falha ao atualizar perfil"));
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["player-profile", "me"] });
    },
  });
}

"use client";

import { useQuery } from "@tanstack/react-query";
import type { Store, StoresResponse } from "@/types/store";

export type StoresFilter = {
  city?: string;
  country?: string;
  verified?: boolean;
  search?: string;
};

export function useStores(filter?: StoresFilter) {
  return useQuery({
    queryKey: ["stores", filter],
    queryFn: async (): Promise<StoresResponse> => {
      const params = new URLSearchParams();
      if (filter?.city) params.set("city", filter.city);
      if (filter?.country) params.set("country", filter.country);
      if (filter?.verified) params.set("verified_only", "true");
      const res = await fetch(`/api/stores?${params.toString()}`, { cache: "no-store" });
      if (!res.ok) throw new Error("Falha ao carregar lojas");
      const rows = (await res.json()) as Store[];
      const stores = filter?.search
        ? rows.filter(
            (s) =>
              s.name.toLowerCase().includes(filter.search!.toLowerCase()) ||
              (s.city ?? "").toLowerCase().includes(filter.search!.toLowerCase()),
          )
        : rows;
      return { stores, total: stores.length };
    },
  });
}

"use client";

import { useMutation } from "@tanstack/react-query";
import { useRouter } from "next/navigation";

export type CreateStoreData = {
  name: string;
  slug: string;
  description?: string;
  email: string;
  city?: string;
  country?: string;
};

export function useCreateStore() {
  const router = useRouter();

  return useMutation({
    mutationFn: async (data: CreateStoreData) => {
      const res = await fetch("/api/stores", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });
      if (!res.ok) {
        const error = await res.json().catch(() => ({}));
        throw new Error(String(error.detail ?? error.message ?? "Falha ao criar loja"));
      }
      return res.json() as Promise<{ slug: string }>;
    },
    onSuccess: (data) => {
      router.push(`/stores/${data.slug}`);
    },
  });
}

"use client";

import { useQuery } from "@tanstack/react-query";
import type { DecklistDetail } from "@/types/marketplace";

export function useDecklistDetail(id: string) {
  const query = useQuery({
    queryKey: ["marketplace-decklist", id],
    queryFn: async (): Promise<DecklistDetail> => {
      const res = await fetch(`/api/marketplace/decklists/${encodeURIComponent(id)}`, {
        cache: "no-store",
      });
      if (!res.ok) throw new Error("Decklist não encontrada");
      const data = await res.json();
      const listing = data.listing as Record<string, unknown>;
      const reviews = (data.reviews as Array<Record<string, unknown>>) ?? [];
      return {
        id: String(listing.id),
        name: String(listing.name),
        game_code: String(listing.game_code),
        format: String(listing.format),
        description: listing.description ? String(listing.description) : undefined,
        price_cents: Number(listing.price_cents),
        sales_count: Number(listing.sales_count ?? 0),
        average_rating: Number(listing.average_rating ?? 0),
        decklist_data: (listing.decklist_data as Record<string, unknown>) ?? {},
        seller_handle: listing.seller_handle ? String(listing.seller_handle) : undefined,
        seller_name: listing.seller_name ? String(listing.seller_name) : undefined,
        reviews: reviews.map((r) => ({
          id: String(r.id),
          rating: Number(r.rating),
          comment: r.comment ? String(r.comment) : undefined,
          title: r.title ? String(r.title) : undefined,
          handle: r.handle ? String(r.handle) : undefined,
          display_name: r.display_name ? String(r.display_name) : undefined,
        })),
      };
    },
    enabled: Boolean(id),
  });

  return {
    decklist: query.data,
    isLoading: query.isLoading,
    error: query.error,
  };
}

"use client";

import { useQuery } from "@tanstack/react-query";

export type FriendProfile = {
  id: string;
  handle: string;
  display_name: string;
  avatar_url?: string;
  status?: string;
  unread?: number;
  friendship_id?: string;
};

export function useFriends() {
  const friendsQuery = useQuery({
    queryKey: ["friends"],
    queryFn: async (): Promise<FriendProfile[]> => {
      const res = await fetch("/api/social/friends", { cache: "no-store" });
      if (!res.ok) return [];
      return res.json();
    },
  });

  const pendingQuery = useQuery({
    queryKey: ["friends-pending"],
    queryFn: async (): Promise<FriendProfile[]> => {
      const res = await fetch("/api/social/friends/pending", { cache: "no-store" });
      if (!res.ok) return [];
      return res.json();
    },
  });

  return {
    friends: friendsQuery.data ?? [],
    pendingRequests: pendingQuery.data ?? [],
    isLoading: friendsQuery.isLoading || pendingQuery.isLoading,
  };
}

"use client";

import { useQuery } from "@tanstack/react-query";
import type { Community } from "@/types/community";

export function useCommunities() {
  return useQuery({
    queryKey: ["communities"],
    queryFn: async (): Promise<Community[]> => {
      const res = await fetch("/api/social/communities", { cache: "no-store" });
      if (!res.ok) return [];
      const rows = await res.json();
      return (rows as Array<Record<string, unknown>>).map((c) => ({
        id: String(c.id),
        name: String(c.name),
        description: c.description ? String(c.description) : undefined,
        game_code: c.game_code ? String(c.game_code) : undefined,
        member_count: Number(c.member_count ?? 0),
        avatar_url: c.avatar_url ? String(c.avatar_url) : undefined,
      }));
    },
  });
}

