  const [formData, setFormData] = useState({
    name: "",
    slug: "",
    description: "",
    city: "",
    country: "BR",
    email: "",
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    createStore(formData);
  };

  return (
    <MobileLayout>
      <div className="container mx-auto max-w-2xl px-4 py-8">
