    def test_lorcana_exact_60(self):
        raw = "\n".join(f"1 Card {i}" for i in range(60))
        deck = self.adapter.parse_decklist(raw, "STANDARD")
        result = self.adapter.validate_decklist(deck)
        assert result.valid is True


