};

"use client";

import { useQuery } from "@tanstack/react-query";
import { mapJudgeCall, type JudgeCall } from "@/types/judge-calls";

export type JudgeCallsFilters = {
  tournamentId?: string;
  status?: string;
  assignedToMe?: boolean;
  openCalls?: boolean;
};

export function useJudgeCalls(filters: JudgeCallsFilters = {}) {
  const params = new URLSearchParams();
  if (filters.tournamentId) params.set("tournament_id", filters.tournamentId);
  if (filters.status) params.set("status", filters.status);
  if (filters.assignedToMe) params.set("assigned_to_me", "true");
  if (filters.openCalls) params.set("open_calls", "true");

  return useQuery({
    queryKey: ["judge-calls", filters],
    queryFn: async () => {
      const res = await fetch(`/api/judge/calls?${params}`);
      if (!res.ok) throw new Error("Falha ao carregar chamadas");
      const data = (await res.json()) as Record<string, unknown>[];
      return data.map(mapJudgeCall) as JudgeCall[];
    },
    refetchInterval: 8_000,
  });
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { mapJudgeCertification, type JudgeCertification } from "@/types/judge-calls";

export function useJudgeCertification() {
  const query = useQuery({
    queryKey: ["judge-certification"],
    queryFn: async () => {
      const res = await fetch("/api/judge/certifications/me");
      if (res.status === 403) return [] as JudgeCertification[];
      if (!res.ok) throw new Error("Falha ao carregar certificação");
      const data = (await res.json()) as Record<string, unknown>[];
      return data.map(mapJudgeCertification);
    },
  });

  return {
    certifications: query.data ?? [],
    certification: query.data?.[0] ?? null,
    isLoading: query.isLoading,
    error: query.error,
  };
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";

export function useAcceptCall() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (callId: string) => {
      const res = await fetch(`/api/judge/calls/${callId}/accept`, { method: "POST" });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error((err as { detail?: string }).detail ?? "Falha ao aceitar chamada");
      }
      return res.json();
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["judge-calls"] });
    },
  });
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import type { RulingCategory } from "@/types/judge-calls";

export type ResolveCallPayload = {
  callId: string;
  ruling: string;
  rulingCategory: RulingCategory;
  infractingPlayerId?: string;
  infractionType?: string;
  severity?: string;
};

export function useResolveCall() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (payload: ResolveCallPayload) => {
      const res = await fetch(`/api/judge/calls/${payload.callId}/resolve`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ruling: payload.ruling,
          ruling_category: payload.rulingCategory,
          infracting_player_id: payload.infractingPlayerId,
          infraction_type: payload.infractionType,
          severity: payload.severity,
        }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error((err as { detail?: string }).detail ?? "Falha ao resolver chamada");
      }
      return res.json();
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["judge-calls"] });
    },
  });
}

export function useEscalateCall() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async ({ callId, reason }: { callId: string; reason: string }) => {
      const res = await fetch(`/api/judge/calls/${callId}/escalate`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ reason }),
      });
      if (!res.ok) throw new Error("Falha ao escalar chamada");
      return res.json();
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["judge-calls"] });
    },
  });
}

import { NextRequest, NextResponse } from "next/server";
import { TOURNAMENT_API_BASE, tournamentProxyHeaders } from "@/lib/tournament-api";

const BASE = `${TOURNAMENT_API_BASE}/runtime/judge/judge`;

export async function GET(req: NextRequest) {
  const url = new URL(req.url);
  try {
    const res = await fetch(`${BASE}/calls?${url.searchParams}`, {
      headers: await tournamentProxyHeaders(),
      cache: "no-store",
    });
    const text = await res.text();
    return new NextResponse(text, { status: res.status, headers: { "Content-Type": "application/json" } });
  } catch {
    return NextResponse.json({ detail: "API indisponível" }, { status: 503 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.text();
    const res = await fetch(`${BASE}/calls`, {
      method: "POST",
      headers: await tournamentProxyHeaders(),
      body,
      cache: "no-store",
    });
    const text = await res.text();
    return new NextResponse(text, { status: res.status, headers: { "Content-Type": "application/json" } });
  } catch {
    return NextResponse.json({ detail: "API indisponível" }, { status: 503 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { TOURNAMENT_API_BASE, tournamentProxyHeaders } from "@/lib/tournament-api";

const BASE = `${TOURNAMENT_API_BASE}/runtime/judge/judge`;

type Params = { params: Promise<{ callId: string; action: string }> };

export async function POST(_req: NextRequest, { params }: Params) {
  const { callId, action } = await params;
  const allowed = new Set(["accept", "resolve", "escalate"]);
  if (!allowed.has(action)) {
    return NextResponse.json({ detail: "Ação inválida" }, { status: 404 });
  }

  try {
    const body = action === "accept" ? undefined : await _req.text();
    const res = await fetch(`${BASE}/calls/${callId}/${action}`, {
      method: "POST",
      headers: await tournamentProxyHeaders(),
      body: body && body.length > 0 ? body : undefined,
      cache: "no-store",
    });
    const text = await res.text();
    return new NextResponse(text, { status: res.status, headers: { "Content-Type": "application/json" } });
  } catch {
    return NextResponse.json({ detail: "API indisponível" }, { status: 503 });
  }
}

