                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {!reportsLoading && reports.length === 0 && (
            <p className="px-3 py-6 text-center text-white/50">Nenhum report aberto.</p>
          )}
        </div>
      </div>
    </section>
  );
}

