CREATE MATERIALIZED VIEW leaderboard_cache AS
SELECT
  r.game_code,
  r.format,
  r.player_id,
  r.points,
  r.tier,
  ROW_NUMBER() OVER (
    PARTITION BY r.game_code, r.format
    ORDER BY r.points DESC
